import React, { useState } from 'react';
import { X, ChevronRight, ChevronLeft, CheckCircle2, AlertCircle } from 'lucide-react';
import Button from './ui/Button';

const questions = [
  "Little interest or pleasure in doing things",
  "Feeling down, depressed, or hopeless",
  "Trouble falling or staying asleep, or sleeping too much",
  "Feeling tired or having little energy",
  "Poor appetite or overeating",
  "Feeling bad about yourself — or that you are a failure or have let yourself or your family down",
  "Trouble concentrating on things, such as reading the newspaper or watching television",
  "Moving or speaking so slowly that other people could have noticed? Or the opposite — being so fidgety or restless that you have been moving around a lot more than usual",
  "Thoughts that you would be better off dead or of hurting yourself in some way"
];

const options = [
  { label: "Not at all", value: 0 },
  { label: "Several days", value: 1 },
  { label: "More than half the days", value: 2 },
  { label: "Nearly every day", value: 3 }
];

interface PHQScreenerProps {
  isOpen: boolean;
  onClose: () => void;
}

const PHQScreener: React.FC<PHQScreenerProps> = ({ isOpen, onClose }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [answers, setAnswers] = useState<number[]>(new Array(questions.length).fill(-1));
  const [showResult, setShowResult] = useState(false);

  if (!isOpen) return null;

  const handleAnswer = (value: number) => {
    const newAnswers = [...answers];
    newAnswers[currentStep] = value;
    setAnswers(newAnswers);

    if (currentStep < questions.length - 1) {
      setTimeout(() => setCurrentStep(currentStep + 1), 300);
    } else {
      setShowResult(true);
    }
  };

  const calculateScore = () => answers.reduce((a, b) => a + b, 0);

  const getFeedback = (score: number) => {
    if (score <= 4) return { level: "Minimal", color: "text-green-600", advice: "Your scores suggest minimal symptoms. Continue your wellness routine." };
    if (score <= 9) return { level: "Mild", color: "text-yellow-600", advice: "You're experiencing mild symptoms. We recommend regular check-ins and self-help tools." };
    if (score <= 14) return { level: "Moderate", color: "text-orange-600", advice: "Moderate symptoms detected. It might be beneficial to speak with one of our counselors." };
    return { level: "Moderately Severe to Severe", color: "text-red-600", advice: "Significant symptoms detected. Please consider booking an urgent session with a professional counselor." };
  };

  const score = calculateScore();
  const feedback = getFeedback(score);
  const progressPercent = ((currentStep + 1) / questions.length) * 100;

  return (
    <div 
      className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="phq9-title"
    >
      <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden relative animate-in fade-in zoom-in duration-300">
        <button 
          onClick={onClose} 
          className="absolute top-6 right-6 text-slate-400 hover:text-slate-600 focus-visible:ring-4 focus-visible:ring-calm-blue/20 rounded-full"
          aria-label="Close Screener"
        >
          <X size={24} />
        </button>

        {!showResult ? (
          <div className="p-8 md:p-12">
            <div className="mb-8">
              <span className="text-calm-blue font-bold text-sm uppercase tracking-widest" id="phq9-step">
                Question {currentStep + 1} of {questions.length}
              </span>
              <div 
                className="w-full bg-gray-100 h-2 rounded-full mt-2"
                role="progressbar"
                aria-valuenow={currentStep + 1}
                aria-valuemin={1}
                aria-valuemax={questions.length}
                aria-labelledby="phq9-step"
              >
                <div 
                  className="bg-calm-blue h-2 rounded-full transition-all duration-500" 
                  style={{ width: `${progressPercent}%` }}
                ></div>
              </div>
            </div>

            <h3 className="text-2xl font-bold text-slate-800 mb-8 min-h-[4rem]" id="phq9-title">
              {questions[currentStep]}
            </h3>

            <div className="space-y-3" role="group" aria-labelledby="phq9-title">
              {options.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => handleAnswer(opt.value)}
                  className={`w-full text-left p-5 rounded-2xl border-2 transition-all duration-200 flex justify-between items-center group ${
                    answers[currentStep] === opt.value 
                    ? 'border-calm-blue bg-blue-50 text-calm-blue' 
                    : 'border-gray-100 hover:border-blue-200 hover:bg-gray-50 text-slate-600'
                  }`}
                  aria-pressed={answers[currentStep] === opt.value}
                >
                  <span className="font-medium">{opt.label}</span>
                  <ChevronRight size={18} className={`transition-transform group-hover:translate-x-1 ${answers[currentStep] === opt.value ? 'opacity-100' : 'opacity-0'}`} />
                </button>
              ))}
            </div>

            <div className="mt-8 flex justify-between items-center">
              <button 
                onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
                disabled={currentStep === 0}
                className="text-slate-500 hover:text-slate-700 disabled:opacity-0 flex items-center gap-1 font-bold transition-colors p-2"
                aria-label="Previous Question"
              >
                <ChevronLeft size={20} /> Previous
              </button>
            </div>
          </div>
        ) : (
          <div className="p-8 md:p-12 text-center">
            <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-6 text-calm-blue">
              <CheckCircle2 size={40} />
            </div>
            <h3 className="text-3xl font-bold text-slate-900 mb-2" id="phq9-result-title">Assessment Complete</h3>
            <p className="text-slate-500 mb-8">Based on the PHQ-9 standardized clinical scale.</p>

            <div className="bg-slate-50 rounded-3xl p-8 mb-8 border border-slate-100">
              <div className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-1">Your Severity Score</div>
              <div className={`text-5xl font-black mb-4 ${feedback.color}`} aria-live="polite">
                {score} <span className="text-xl text-slate-300 font-normal">/ 27</span>
              </div>
              <div className={`text-xl font-bold mb-3 ${feedback.color}`}>{feedback.level} Symptoms</div>
              <p className="text-slate-600 max-w-sm mx-auto">{feedback.advice}</p>
            </div>

            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <Button onClick={onClose} variant="outline" className="w-full sm:w-auto">Finish</Button>
              <Button onClick={() => { onClose(); document.getElementById('counselors')?.scrollIntoView({ behavior: 'smooth' }); }} variant="primary" className="w-full sm:w-auto">Book a Session</Button>
            </div>

            <div className="mt-8 flex items-center justify-center gap-2 text-xs text-slate-500">
              <AlertCircle size={14} />
              <span>This is a screening tool, not a diagnosis. For emergencies, please call local emergency services.</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default PHQScreener;

