    setIsMobileMenuOpen(false);
    if (onClick) onClick();
  };

  return (
    <header 
      className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-500 ${
        isScrolled ? 'bg-white/80 backdrop-blur-xl shadow-lg py-4 border-b border-white/20' : 'bg-transparent py-6'
