import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Bot, User, Sparkles, Loader2 } from 'lucide-react';
import { GoogleGenAI } from '@google/genai';
import Button from './ui/Button';

const AIChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{role: 'user' | 'bot', text: string}[]>([
    { role: 'bot', text: 'Hello! I am your MindLens Assistant. How can I help you today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [hasAutoOpened, setHasAutoOpened] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!hasAutoOpened) {
        setIsOpen(true);
        setHasAutoOpened(true);
      }
    }, 2500);
    return () => clearTimeout(timer);
  }, [hasAutoOpened]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: `You are the MindLens AI Assistant. Be compassionate and helpful.`,
          temperature: 0.7,
        },
      });
      setMessages(prev => [...prev, { role: 'bot', text: response.text || "I'm sorry, I'm having trouble." }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'bot', text: "Error encountered." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 left-6 z-[1000] flex flex-col items-start pointer-events-none w-fit">
      <section 
        className={`mb-4 w-[320px] sm:w-[400px] glass-card rounded-[32px] border border-white/40 shadow-2xl overflow-hidden flex flex-col h-[500px] transition-all duration-500 transform origin-bottom-left pointer-events-auto ${
          isOpen ? 'scale-100 opacity-100' : 'scale-75 opacity-0 pointer-events-none'
        }`}
      >
        <div className="bg-calm-blue p-5 flex items-center justify-between text-white">
          <div className="flex items-center gap-3">
            <Sparkles size={20} />
            <span className="font-bold">MindLens AI</span>
          </div>
          <button onClick={() => setIsOpen(false)} className="hover:bg-white/10 p-2 rounded-lg">
            <X size={20} />
          </button>
        </div>
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-4 bg-white/50 custom-scrollbar">
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`p-4 rounded-2xl max-w-[85%] text-sm ${m.role === 'user' ? 'bg-calm-blue text-white' : 'bg-white text-slate-700 shadow-sm'}`}>
                {m.text}
              </div>
            </div>
          ))}
        </div>
        <div className="p-4 bg-white border-t border-slate-100 flex gap-2">
          <input 
            type="text" 
            className="flex-1 bg-slate-50 border border-slate-100 rounded-xl px-4 py-2 text-sm outline-none"
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder="Type message..."
          />
          <button onClick={handleSend} className="bg-calm-blue text-white p-2 rounded-xl"><Send size={18} /></button>
        </div>
      </section>

      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="w-14 h-14 bg-calm-blue text-white rounded-2xl shadow-xl flex items-center justify-center hover:scale-105 active:scale-95 transition-all pointer-events-auto"
      >
        {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
      </button>
    </div>
  );
};

export default AIChatBot;

